#!/usr/bin/env node
// Generates go/internal/instructions/fallback_gen.go from the JS fallback
// ruleset, so the Go port cannot drift from hooks/ponytail-instructions.js.
// The generated file is committed; building the Go port needs no Node.
//
// Run: node scripts/gen-go-fallback.js  (or: go generate ./internal/instructions)

const fs = require('fs');
const path = require('path');
const { getFallbackInstructions } = require('../hooks/ponytail-instructions.js');

const SENTINEL = 'SENTINELMODE';
const INTENSITY_FULL =
  'The ladder enforced. Stdlib and native first. Shortest diff, shortest explanation.';

const text = getFallbackInstructions(SENTINEL);
const header = 'PONYTAIL MODE ACTIVE — level: ' + SENTINEL + '\n\n';
if (!text.startsWith(header)) throw new Error('fallback header shape changed');

const rest = text.slice(header.length);
const middle =
  'Current level: **' + SENTINEL + '** — ' + INTENSITY_FULL +
  ' Switch: `/ponytail lite|full|ultra`.\n\n';
const split = rest.indexOf(middle);
if (split < 0) throw new Error('fallback "Current level" line shape changed');

const head = rest.slice(0, split);
const tail = rest.slice(split + middle.length);
// The sentinel must appear exactly where the Go code re-inserts the mode.
if (head.includes(SENTINEL) || tail.includes(SENTINEL)) {
  throw new Error('mode sentinel appears outside the two known slots');
}

// One Go interpreted-string literal per source line keeps the generated file
// diffable; JSON.stringify is already a valid Go string literal for this text.
function goLiteral(value) {
  const lines = value.split('\n');
  return lines
    .map((line, i) => JSON.stringify(i < lines.length - 1 ? line + '\n' : line))
    .filter((literal) => literal !== '""')
    .map((literal) => '\t' + literal)
    .join(' +\n');
}

const out = `// Code generated by scripts/gen-go-fallback.js. DO NOT EDIT.
// Source of truth: hooks/ponytail-instructions.js (getFallbackInstructions).

package instructions

// fallbackHead is the ruleset text between the mode header and the
// "Current level" line.
const fallbackHead = "" +
${goLiteral(head)}

// fallbackTail is the ruleset text after the "Current level" line.
const fallbackTail = "" +
${goLiteral(tail)}
`;

const target = path.join(__dirname, '..', 'go', 'internal', 'instructions', 'fallback_gen.go');
fs.writeFileSync(target, out, 'utf8');
console.log('Wrote ' + path.relative(path.join(__dirname, '..'), target));
